package com.exe201.rrms.controller;
import com.exe201.rrms.entity.*;import com.exe201.rrms.repository.*;import com.exe201.rrms.service.MarketplaceService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/properties") public class PropertyController {private final PropertyRepository props;private final ListingRepository listings;private final MarketplaceService market;public PropertyController(PropertyRepository p,ListingRepository l,MarketplaceService m){props=p;listings=l;market=m;} @GetMapping public List<Property>all(){return props.findAll();} @GetMapping("/{id}") public Property one(@PathVariable Long id){return props.findById(id).orElseThrow();} @GetMapping("/available") public List<Map<String,Object>> available(@RequestParam(required=false)String search){Map<String,String>q=new HashMap<>();if(search!=null)q.put("search",search);return market.search(q);} @GetMapping("/landlord/{id}") public List<Property> landlord(@PathVariable Long id){return props.findByLandlordId(id);} }
